  'reading.deleteForever': ['Delete permanently', 'Xoá vĩnh viễn', 'Hapus permanen', 'स्थायी रूप से हटाएँ', '永久删除', 'Удалить навсегда', '完全に削除', 'Excluir permanentemente', 'Eliminar para siempre'],
  'reading.deleteFailed': ['Could not delete this reading.', 'Không thể xoá lần xem bói.', 'Tidak dapat menghapus pembacaan.', 'रीडिंग हटाई नहीं जा सकी।', '无法删除此解读。', 'Не удалось удалить толкование.', '鑑定を削除できませんでした。', 'Não foi possível excluir a leitura.', 'No se pudo eliminar la lectura.'],
  'reading.copiedShare': ['Share text copied to the clipboard.', 'Đã sao chép nội dung chia sẻ vào bộ nhớ tạm.', 'Teks berbagi disalin ke papan klip.', 'शेयर टेक्स्ट क्लिपबोर्ड पर कॉपी हुआ।', '分享内容已复制到剪贴板。', 'Текст скопирован в буфер обмена.', '共有テキストをクリップボードにコピーしました。', 'Texto copiado para a área de transferência.', 'Texto copiado al portapapeles.'],
  'reading.shareDiagram': ['Share palm diagram', 'Chia sẻ sơ đồ chỉ tay', 'Bagikan diagram tangan', 'हस्तरेखा आरेख साझा करें', '分享掌纹图', 'Поделиться схемой ладони', '手相図を共有', 'Compartilhar diagrama da mão', 'Compartir diagrama de la mano'],
  'reading.shareTextA11y': ['Share result text', 'Chia sẻ văn bản kết quả', 'Bagikan teks hasil', 'परिणाम टेक्स्ट साझा करें', '分享结果文本', 'Поделиться текстом результата', '結果のテキストを共有', 'Compartilhar texto do resultado', 'Compartir texto del resultado'],
